class ComponentTale {
  constructor({taleOriginName, taleName}) {
    this.taleOriginName = taleOriginName;
    this.taleName = taleName;
    this.extensionCount = 0;
    this.Component = null; // todo: ? maybe push a default component from configuration (to expose init props to every subsequent tale)
    this.setComponent = this.setComponent.bind (this);
  }

  setComponent (Component) {
    this.Component = Component;
    this.extensionCount++;
  }
}

module.exports = ComponentTale;
